const cfg = $input.first().json;
let actorInput; try { actorInput = JSON.parse(cfg.actorInputJson); } catch (error) { throw new Error(`actorInputJson must be valid JSON: ${error.message}`); }
if (!actorInput || Array.isArray(actorInput)) throw new Error('actorInputJson must be one object');
if (actorInput.mode !== 'search' || !actorInput.search || !Array.isArray(actorInput.search.keywords) || actorInput.search.keywords.length < 1) throw new Error('starter requires explicit search keywords');
if (!Number.isInteger(actorInput.maxItems) || actorInput.maxItems < 1 || actorInput.maxItems > 5) throw new Error('starter maxItems must be 1 through 5');
if (cfg.actorBuild !== '0.1.22') throw new Error('actorBuild must remain pinned to verified build 0.1.22');
if (Number(cfg.maxTotalChargeUsd) !== 0.10) throw new Error('starter charge cap must be USD 0.10');
if (!Number.isInteger(cfg.maxPollSeconds) || cfg.maxPollSeconds < 60 || cfg.maxPollSeconds > 600) throw new Error('maxPollSeconds must be 60 through 600');
if (!cfg.googleSpreadsheetId || cfg.googleSpreadsheetId.startsWith('REPLACE_WITH_')) throw new Error('replace googleSpreadsheetId before running');
if (!cfg.googleSheetName) throw new Error('googleSheetName is required');
return [{json:{...cfg,actorInput}}];

const envelope = $input.first().json;
const run = envelope && typeof envelope === 'object' ? (envelope.data || envelope) : {};
if (!run.id || typeof run.status !== 'string') throw new Error('Apify returned no exact run ID/status');
const terminal = new Set(['SUCCEEDED','FAILED','ABORTED','TIMED-OUT']);
if (!terminal.has(run.status)) {
  const started = Date.parse(run.startedAt), maxSeconds = Number($('Configuration').first().json.maxPollSeconds);
  if (!Number.isFinite(started) || (Date.now()-started)/1000 > maxSeconds) throw new Error(`Actor polling deadline exceeded after ${maxSeconds} seconds`);
}
return [{json:run}];

const run = $input.first().json.data || $input.first().json;
const expected = $('Configuration').first().json.actorBuild;
if (run.status !== 'SUCCEEDED' || run.exitCode !== 0) throw new Error(`Actor run ended ${run.status} exitCode=${run.exitCode}`);
if (run.buildNumber !== expected) throw new Error(`Actor used build ${run.buildNumber}; expected ${expected}`);
if (!run.id || !run.defaultDatasetId || !run.defaultKeyValueStoreId) throw new Error('terminal run is missing immutable storage IDs');
return [{json:{runId:run.id,datasetId:run.defaultDatasetId,keyValueStoreId:run.defaultKeyValueStoreId}}];

const summary = $input.first().json.body || $input.first().json.data || $input.first().json;
const acceptedSchemas = new Set(['nomad-ai-job-fit-run-summary-v3','nomad-ai-job-fit-run-summary-v4']);
if (!summary || !acceptedSchemas.has(summary.schemaVersion)) throw new Error('invalid RUN-SUMMARY schema');
if (!['complete','partial','empty'].includes(summary.status)) throw new Error(`unusable RUN-SUMMARY status ${summary.status}`);
if (!summary.algorithm || summary.algorithm.name !== 'scoring-v3' || summary.algorithm.interactionStateUsed !== false) throw new Error('unexpected scoring algorithm');
if (!summary.counts || !Number.isInteger(summary.counts.outputRows) || summary.counts.outputRows < 0) throw new Error('invalid outputRows');
if (!summary.ai || summary.ai.providerCostLimitUsd !== 0.25 || summary.ai.maxProviderAttempts !== 2 || typeof summary.ai.providerCostLimited !== 'boolean' || typeof summary.ai.providerCostReservedUsd !== 'number' || summary.ai.providerCostReservedUsd < 0 || summary.ai.providerCostReservedUsd > 0.25) throw new Error('unexpected owner provider cost guard');
const expectedBillingKeys = ['budgetAuthorizedCount','budgetLimited','chargedCount','eventName','totalChargedUsd','unitPriceUsd'].sort();
if (!summary.billing || JSON.stringify(Object.keys(summary.billing).sort()) !== JSON.stringify(expectedBillingKeys) || summary.billing.eventName !== 'job-fit-result' || summary.billing.unitPriceUsd !== 0.02 || !Number.isInteger(summary.billing.chargedCount) || summary.billing.chargedCount < 0) throw new Error('unexpected billing contract');
const expectedTotal = summary.billing.chargedCount * 0.02;
if (Math.abs(summary.billing.totalChargedUsd - expectedTotal) > 0.0000001) throw new Error('total charged amount does not reconcile');
if (summary.status === 'empty' && (!summary.cleanEmpty || summary.counts.outputRows !== 0)) throw new Error('invalid clean-empty summary');
if (summary.schemaVersion === 'nomad-ai-job-fit-run-summary-v4') {
  const countNames = ['evaluatedJobs','staticDropped','staticHeld','aiScored','aiFailed','resultFilteredOut','outputRows'];
  if (countNames.some(name => !Number.isInteger(summary.counts[name]) || summary.counts[name] < 0)) throw new Error('invalid v4 evaluation counts');
  if (summary.counts.staticDropped + summary.counts.staticHeld + summary.counts.aiScored + summary.counts.aiFailed !== summary.counts.evaluatedJobs) throw new Error('v4 evaluation counts do not partition evaluatedJobs');
  if (summary.counts.resultFilteredOut + summary.counts.outputRows !== summary.counts.evaluatedJobs) throw new Error('v4 filtered and output counts do not reconcile');
  if (!summary.parameters || !['shortlist','audit'].includes(summary.parameters.resultMode) || !Number.isInteger(summary.parameters.minDeliveryScore) || summary.parameters.minDeliveryScore < 0 || summary.parameters.minDeliveryScore > 5) throw new Error('invalid v4 result policy');
  const expectedCharged = summary.parameters.resultMode === 'shortlist' ? summary.counts.outputRows : summary.counts.outputRows - summary.counts.aiFailed;
  if (summary.parameters.resultMode === 'audit' && (summary.counts.resultFilteredOut !== 0 || summary.counts.outputRows !== summary.counts.evaluatedJobs)) throw new Error('v4 audit counts do not preserve the complete dataset');
  if (summary.billing.chargedCount !== expectedCharged) throw new Error('v4 billing does not reconcile with result policy');
}
return [{json:summary}];

const rows = $input.all().flatMap(item => Array.isArray(item.json) ? item.json : [item.json]);
const summary = $('Validate RUN-SUMMARY').first().json;
if (!summary || rows.length !== summary.counts.outputRows) throw new Error(`Dataset rows ${rows.length} do not match RUN-SUMMARY outputRows ${summary && summary.counts && summary.counts.outputRows}`);
const isV4 = summary.schemaVersion === 'nomad-ai-job-fit-run-summary-v4';
const expectedKeys = ['blockingGates','candidateHash','candidateSnapshotHash','company','deliveryScore','evaluatedAt','evaluationKey','evaluationStatus','externalId','fitScore','gapSummary','gates','job','jobKey','location','matchKey','postedAt','recommendation','schemaVersion','scoreAdjustedForGates','scoring','source','staticDecision','title','url','why'].sort();
const sha256 = /^[a-f0-9]{64}$/;
const statuses = new Set(['scored','static_drop','static_hold','forward_cap_hold','ai_failed']);
const bounded = row => {
  const raw = JSON.stringify(row);
  return raw.length <= 48000 ? raw : JSON.stringify({_truncated:true,originalChars:raw.length,schemaVersion:row.schemaVersion,matchKey:row.matchKey,jobKey:row.jobKey});
};
const output = [];
const seen = new Set();
for (const row of rows) {
  if (!row || typeof row !== 'object' || Array.isArray(row)) throw new Error('fit row must be an object');
  if (JSON.stringify(Object.keys(row).sort()) !== JSON.stringify(expectedKeys) || row.schemaVersion !== 'nomad-ai-job-fit-v1') throw new Error('fit row must be exact nomad-ai-job-fit-v1');
  if (!sha256.test(row.matchKey) || !sha256.test(row.evaluationKey) || !sha256.test(row.candidateHash) || !sha256.test(row.candidateSnapshotHash)) throw new Error('invalid fit row hashes');
  if (!statuses.has(row.evaluationStatus)) throw new Error('unknown evaluationStatus');
  if (!row.job || row.job.schemaVersion !== 'nomad-agent-job-v1') throw new Error('missing canonical job');
  if (!row.scoring || row.scoring.algorithm !== 'scoring-v3' || !row.scoring.sourceProvenance) throw new Error('missing v3 provenance');
  if (isV4 && summary.parameters.resultMode === 'shortlist' && (row.evaluationStatus !== 'scored' || !Number.isInteger(row.deliveryScore) || row.deliveryScore < summary.parameters.minDeliveryScore)) throw new Error('shortlist row violates the v4 delivery policy');
  if (row.evaluationStatus === 'ai_failed') continue;
  if (seen.has(row.matchKey)) throw new Error(`duplicate matchKey ${row.matchKey}`);
  seen.add(row.matchKey);
  const provenance = row.scoring.sourceProvenance;
  output.push({json:{
    schemaVersion:'nomad-ai-job-fit-destination-v1', matchKey:row.matchKey, evaluationKey:row.evaluationKey, jobKey:row.jobKey,
    candidateHash:row.candidateHash, candidateSnapshotHash:row.candidateSnapshotHash, evaluatedAt:row.evaluatedAt,
    fitScore:row.fitScore, deliveryScore:row.deliveryScore,
    recommendation:row.recommendation, evaluationStatus:row.evaluationStatus,
    title:row.title, company:row.company, location:row.location, url:row.url,
    blockingGatesJson:JSON.stringify(row.blockingGates), why:row.why, gapSummary:row.gapSummary,
    sourceRunId:provenance.actorRunId || null, sourceBuild:provenance.buildNumber || provenance.buildId || null,
    evaluationJson:bounded(row),
  }});
}
const retainedNonFailures = rows.filter(row => row.evaluationStatus !== 'ai_failed').length;
const expectedCharged = isV4 && summary.parameters.resultMode === 'shortlist' ? rows.length : retainedNonFailures;
if (summary.billing.chargedCount !== expectedCharged) throw new Error(`Charged ${summary.billing.chargedCount} but result policy requires ${expectedCharged} charged rows`);
return output;
